import express from 'express';
import {
  getAppointments,
  getAppointmentById,
  createAppointment,
  updateAppointment,
  deleteAppointment
} from '../controllers/appointmentController';
import { auth, restrictTo } from '../middleware/auth';

const router = express.Router();

// Public routes
router.get('/', getAppointments);
router.get('/:id', getAppointmentById);

// Protected routes
router.use(auth);
router.post('/', restrictTo('patient', 'admin'), createAppointment);
router.patch('/:id', restrictTo('patient', 'doctor', 'admin'), updateAppointment);
router.delete('/:id', restrictTo('patient', 'admin'), deleteAppointment);

export default router; 